339	    while (!g_shutdown_requested) {
340	        agent_msg_t msg;
341	        /* Wait indefinitely rather than polling once a second. There is
342	         * nothing to do on a timeout -- the loop just goes round -- and the
343	         * timeout costs a full timed release-and-reacquire of the queue's
344	         * mutex every second for the life of the device, which is a lot of
345	         * traffic through the scheduler's mutex bookkeeping for no gain.
346	         * Shutdown wakes this with a broadcast, so it cannot get stuck. */
347	        if (message_bus_pop_outbound(&msg, UINT32_MAX) != OK)
348	            continue;
349	        msg.channel[sizeof(msg.channel) - 1] = '\0';
350	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
351	
352	        if (!msg.content) {
353	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
354	            continue;
355	        }
356	
357	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
358	
359	        /* Mirror to the watch screen, whatever channel this is bound for.
360	         *
361	         * A reply is only routed to the channel it came from, so an exchange
362	         * over voice or WebSocket is invisible on the device even though the
363	         * device is what did the work. Mirroring at this one point covers
364	         * every channel at once -- including cron wake-ups and proactive
365	         * pushes -- instead of adding a special case to each path that
366	         * happens to remember. Skipped when the screen is already the
367	         * destination, which would otherwise double up. */
368	#ifdef CONFIG_AI_AGENT_LVGL_UI
369	        if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) != 0) {
370	            lvgl_ui_channel_post(msg.content);
371	        }
372	#endif
373	
374	        /* Let registered taps intercept before normal dispatch */
375	        if (mbus_tap_try_deliver(&msg)) {
376	            free(msg.content);
377	            continue;
378	        }
379	
380	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
381	            bool delivered = false;
382	#ifdef CONFIG_AI_AGENT_FEISHU
383	            const char* app_id = feishu_get_app_id();
384	            if (app_id && app_id[0] != '\0') {
385	                feishu_send_message(msg.chat_id, msg.content);
386	                delivered = true;
387	            }
388	#endif
389	#ifdef CONFIG_AI_AGENT_NODE
390	            if (!delivered) {
391	                delivered = node_client_send_chat_message(
392	                    msg.channel, msg.chat_id, msg.content) == OK;
393	            }
394	#endif
395	            if (!delivered) {
396	                syslog(LOG_WARNING,
397	                    "[%s] Feishu message dropped: no local config "
398	                    "and no gateway\n",
399	                    TAG);
400	            }
401	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
402	            ws_server_send(msg.chat_id, msg.content);
403	#ifdef CONFIG_AI_AGENT_MQTT
404	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
405	            mqtt_channel_send(msg.chat_id, msg.content);
406	#endif
407	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
408	            /* Check voice cooldown — skip voice dispatch if a recent
409	             * speak call failed, to prevent error-message cascade. */
410	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
411	                syslog(LOG_WARNING,
412	                    "[%s] voice cooldown active, dropping message\n", TAG);
413	            } else {
414	                s_voice_cooldown = false;
415	                int vret = voice_channel_speak(msg.content);
416	                if (vret != 0) {
417	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
418	                    s_voice_cooldown = true;
419	                    s_voice_cooldown_until = time(NULL) + 5;
420	                }
421	            }
422	#ifdef CONFIG_AI_AGENT_LVGL_UI
423	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
424	            int uret = lvgl_ui_channel_send(msg.content);
425	            if (uret != 0) {
426	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
427	            }
428	#endif
429	#ifdef CONFIG_AI_AGENT_WEIXIN
430	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
431	            /* chat_id format: "from_user_id|context_token" */
432	            char uid[64] = "";
433	            const char* ctx = "";
434	            char* sep = strchr(msg.chat_id, '|');
435	            if (sep) {
436	                size_t ulen = (size_t)(sep - msg.chat_id);
437	                if (ulen >= sizeof(uid))
438	                    ulen = sizeof(uid) - 1;
439	                memcpy(uid, msg.chat_id, ulen);
440	                uid[ulen] = '\0';
441	                ctx = sep + 1;
442	            } else {
443	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
444	            }
445	            weixin_channel_send(uid, ctx, msg.content);
446	#endif
447	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
448	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
449	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
450	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
451	            quickapp_mq_dispatch(msg.chat_id, msg.content);
452	#endif
453	        } else if (strcmp(msg.channel, "cli") == 0) {
454	            pthread_mutex_lock(&g_stdout_lock);
455	            printf("\n[Agent]: %s\nvela> ", msg.content);
456	            fflush(stdout);
457	            pthread_mutex_unlock(&g_stdout_lock);
458	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
459	        } else {
460	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
461	        }
462	
463	        free(msg.content);
464	    }
465	
466	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
467	    return NULL;
468	}
