808	int ws_server_send(const char* chat_id, const char* text)
809	{
810	    if (s_listen_fd < 0 || !s_running)
811	        return ERROR;
812	
813	    /* Build JSON response */
814	    cJSON* resp = cJSON_CreateObject();
815	    cJSON_AddStringToObject(resp, "type", "response");
816	    cJSON_AddStringToObject(resp, "content", text);
817	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
818	    char* json_str = cJSON_PrintUnformatted(resp);
819	    cJSON_Delete(resp);
820	    if (!json_str)
821	        return ERROR;
822	
823	    ws_client_t* client = lock_client_for_send(chat_id);
824	    int rc = -1;
825	    if (client) {
826	        rc = ws_send_frame(client, json_str, strlen(json_str));
827	        if (rc != 0) {
828	            syslog(
829	                LOG_WARNING,
830	                "[%s] Send failed to %s (fd will be cleaned up by client thread)\n",
831	                TAG, chat_id);
832	            /* Don't remove/close here — the client_thread owns the fd lifecycle.
833	             * The recv() in client_thread will fail and trigger cleanup. */
834	        }
835	        unlock_client(client);
836	    } else {
837	        syslog(LOG_WARNING, "[%s] No WS client for chat_id=%s\n", TAG, chat_id);
838	    }
839	
840	    free(json_str);
841	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
842	}
