432	/* LVGL event loop — only used when we brought LVGL up ourselves.
433	 * The host system (miwear) normally drives lv_timer_handler() for us. */
434	static void* lvgl_event_loop(void* arg)
435	{
436	    (void)arg;
437	
438	    /* Keep pumping until teardown finishes: lvgl_ui_channel_stop() clears
439	     * "running" first and then relies on this loop to run the queued
440	     * lv_async_call() cleanup, so keying on "running" would abort it. */
441	    while (s_state.initialized) {
442	        uint32_t idle;
443	
444	        /* Put anything other threads have queued on screen first, then let
445	         * LVGL do its own work. This is the only place widgets get touched. */
446	        ui_drain();
447	
448	        idle = lv_timer_handler();
449	
450	        /* Never busy-spin, but do not sleep so long that a queued line sits
451	         * there visibly late either. */
452	        if (idle > 50) {
453	            idle = 50;
454	        }
455	        usleep((idle ? idle : 5) * 1000);
456	    }
457	
458	    return NULL;
459	}
