790	    s_show_requested = false;
791	
792	    while (s_queue_count > 0 && n < UI_QUEUE_MAX) {
793	        batch[n++] = s_queue[s_queue_head];
794	        s_queue[s_queue_head] = NULL;
795	        s_queue_head = (s_queue_head + 1) % UI_QUEUE_MAX;
796	        s_queue_count--;
