805	    for (i = 0; i < n; i++) {
806	        chat_view_add_message(batch[i]->text, batch[i]->is_user);
807	        free(batch[i]);
808	        batch[i] = NULL;
809	    }
810	
811	    /* A line landing means recognition finished -- either the recognised
812	     * command itself or the answer to it -- so the "识别中..." indicator has
813	     * done its job and goes back to idle. */
814	    if (n > 0 && s_state.is_processing) {
815	        s_state.is_processing = false;
816	        recording_indicator_stop();
