857	
858	    /* If history is already full, trim before overwriting */
859	    if (h->count == CHAT_HISTORY_MAX) {
860	        chat_view_trim_history();
861	    }
862	
863	    /* Store message in ring buffer (handles truncation + old bubble deletion) */
864	    slot = chat_history_add(h, text, is_user);
865	
866	    /* Create bubble container inside chat_list */
867	    bubble = lv_obj_create(s_state.chat_list);
868	    if (!bubble) {
869	        syslog(LOG_ERR, "[%s] bubble create failed\n", TAG);
870	        return;
871	    }
