873	    lv_obj_set_width(bubble, lv_pct(85));
874	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
875	    lv_obj_set_style_radius(bubble, LVGL_UI_BUBBLE_RADIUS, 0);
876	    lv_obj_set_style_pad_all(bubble, LVGL_UI_BUBBLE_PAD, 0);
877	    lv_obj_set_style_border_width(bubble, 0, 0);
878	
879	    if (is_user) {
880	        /* User bubble: right-aligned, blue background, white text */
881	        lv_obj_set_style_align(bubble, LV_ALIGN_RIGHT_MID, 0);
882	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x3a7bd5), 0);
883	        lv_obj_set_style_text_color(bubble, lv_color_white(), 0);
884	    } else {
885	        /* Agent bubble: left-aligned, semi-transparent dark bg */
886	        lv_obj_set_style_align(bubble, LV_ALIGN_LEFT_MID, 0);
887	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x2a2a40), 0);
888	        lv_obj_set_style_bg_opa(bubble, LV_OPA_90, 0);
889	        lv_obj_set_style_text_color(bubble, lv_color_hex(0xe8e8e8), 0);
890	    }
891	
892	    /* Create label inside bubble */
893	    lbl = lv_label_create(bubble);
894	    if (!lbl) {
895	        syslog(LOG_ERR, "[%s] bubble label create failed\n", TAG);
896	        lv_obj_del(bubble);
897	        slot->bubble = NULL;
898	        return;
899	    }
900	
901	    lv_label_set_text(lbl, slot->text);
902	    lv_label_set_long_mode(lbl, LV_LABEL_LONG_WRAP);
903	    lv_obj_set_width(lbl, lv_pct(100));
904	
905	    slot->bubble = bubble;
