239	/* mic_rate [seconds]
240	 *
241	 * Measure the sample rate the ADC actually produces, rather than the one we
242	 * asked for. ADC_CFG's clk_div/osr_sel fields do not map onto a sample rate
243	 * in any way the tree documents, and the HAL's own values (5 / 0) turn out to
244	 * land near 6.4 kHz rather than the 16 kHz everything downstream assumes.
245	 * Frames on the wire are whole and evenly spaced either way, so a wrong rate
246	 * looks exactly like correct capture until speech recognition mangles it --
247	 * this command is what makes the discrepancy visible.
248	 */
249	void cmd_mic_rate(int argc, char** argv)
250	{
251	    int seconds = (argc >= 2) ? atoi(argv[1]) : 3;
252	    struct timespec t0, t1;
253	    unsigned int total = 0;
254	    uint8_t div, osr;
255	    int16_t* buf;
256	    double elapsed;
257	    int ret;
258	
259	    if (seconds <= 0 || seconds > 30) {
260	        seconds = 3;
261	    }
262	
263	    if (sf32lb_audcodec_is_open()) {
264	        sf32lb_audcodec_close();
265	        usleep(50000);
266	    }
267	
268	    if (argc >= 4) {
269	        sf32lb_audcodec_set_clk((uint8_t)atoi(argv[2]), (uint8_t)atoi(argv[3]));
270	    }
271	
272	    ret = sf32lb_audcodec_open(MIC_TEST_SAMPLE_RATE);
273	    if (ret < 0) {
274	        printf("mic_rate: open failed (%d)\n", ret);
275	        return;
276	    }
277	
278	    buf = malloc(MIC_BLOCK_SAMPLES * sizeof(int16_t));
279	    if (buf == NULL) {
280	        sf32lb_audcodec_close();
281	        printf("mic_rate: out of memory\n");
282	        return;
283	    }
284	
285	    sf32lb_audcodec_get_clk(&div, &osr);
286	
287	    /* Let the analog path settle so the first reads are not the slow ones. */
288	    usleep(200000);
289	
290	    clock_gettime(CLOCK_MONOTONIC, &t0);
291	
292	    for (;;) {
293	        ssize_t n = sf32lb_audcodec_read(buf, MIC_BLOCK_SAMPLES);
294	
295	        if (n < 0) {
296	            break;
297	        }
298	
299	        /* Count what came back, not what was asked for: a read returns as
300	         * soon as it has a useful amount, so assuming the request size here
301	         * would over-report the rate. */
302	
303	        total += (unsigned int)n;
304	
305	        clock_gettime(CLOCK_MONOTONIC, &t1);
306	        elapsed = (t1.tv_sec - t0.tv_sec)
307	                + (t1.tv_nsec - t0.tv_nsec) / 1e9;
308	        if (elapsed >= (double)seconds) {
309	            break;
310	        }
311	    }
312	
313	    free(buf);
314	    sf32lb_audcodec_close();
315	
316	    if (elapsed <= 0.0) {
317	        printf("mic_rate: no samples\n");
318	        return;
319	    }
320	
321	    printf("mic_rate: clk_div=%d osr_sel=%d -> %u samples in %.2f s "
322	           "= %.0f Hz\n", div, osr, total, elapsed, total / elapsed);
323	}
