class ImaAdpcmDecoder:
    """Stateful 4-bit IMA ADPCM decoder (low nibble first).

    The device carries an odd sample's nibble into the next WebSocket frame,
    so the decoder state must live across frames, not be recreated per frame.
    """

    def __init__(self):
        self.reset()

    def reset(self) -> None:
        self.prev = 0
        self.index = 0

    def decode(self, data: bytes) -> bytes:
        out = bytearray(len(data) * 4)   # 2 samples/byte * 2 bytes/sample
        pos = 0
        prev = self.prev
        index = self.index

        for byte in data:
            for nib in (byte & 0x0F, byte >> 4):
                step = IMA_STEP_TABLE[index]
                diff = step >> 3
                if nib & 4:
                    diff += step
                if nib & 2:
                    diff += step >> 1
                if nib & 1:
                    diff += step >> 2
                if nib & 8:
                    prev -= diff
                else:
                    prev += diff
                if prev < -32768:
                    prev = -32768
                elif prev > 32767:
                    prev = 32767

                index += IMA_INDEX_TABLE[nib]
                if index < 0:
                    index = 0
                elif index > 88:
                    index = 88

                sample = prev & 0xFFFF
                out[pos] = sample & 0xFF
                out[pos + 1] = sample >> 8
                pos += 2

        self.prev = prev
        self.index = index
        return bytes(out)

