537	         * next lv_timer_handler() call crashes with a MemManage fault
538	         * (NULL pointer dereference at offset 0x32 in lv_obj_t). */
539	        if (s_state.screen_visible && s_state.prev_screen) {
540	            lv_screen_load(s_state.prev_screen);
541	        }
542	
543	        lv_obj_del(s_state.screen);
544	        s_state.screen = NULL;
545	    }
546	
547	    s_state.screen_visible = false;
548	    s_state.prev_screen = NULL;
549	
550	#if LVGL_UI_HAVE_CJK_FONT
551	    if (s_state.font) {
552	        vg_font_destroy(s_state.font);
553	        s_state.font = NULL;
554	    }
555	#endif
556	
557	    s_state.chat_list = NULL;
558	    s_state.ptt_btn = NULL;
559	    s_state.ptt_label = NULL;

560	    s_state.rec_indicator = NULL;
561	    s_state.close_btn = NULL;
562	
563	    for (i = 0; i < CHAT_HISTORY_MAX; i++) {
564	        s_state.history.msgs[i].bubble = NULL;
565	    }
566	
567	    s_state.history.head = 0;
568	    s_state.history.count = 0;
569	}
