616	/* Stop from an external thread (e.g. velaquit shutdown).
617	 * Schedules cleanup in the LVGL thread to avoid racing with the
618	 * miwear/launcher event loop. */
619	void lvgl_ui_channel_stop(void)
620	{
621	    /* No-op if not initialized or not running */
622	    if (!s_state.initialized || !s_state.running) {
623	        return;
624	    }
625	
626	    syslog(LOG_INFO, "[%s] stopping\n", TAG);
627	
628	    /* Mark as not running first — prevents callbacks (PTT, close_btn,
629	     * chat_view_add_message) from touching widgets during teardown. */
630	    s_state.running = false;
631	
632	    /* Schedule cleanup in the LVGL thread to avoid racing with the
633	     * miwear/launcher event loop.  Direct lv_obj_del from the
634	     * shutdown thread causes a MemManage fault because the LVGL
635	     * thread may be mid-render on the same objects. */
636	    sem_init(&s_stop_sem, 0, 0);
637	    lv_async_call(stop_screen_async_cb, NULL);
638	
639	    /* Wait for LVGL thread to complete the deletion (timeout 2s) */
640	    struct timespec ts;
641	
642	    clock_gettime(CLOCK_REALTIME, &ts);
643	    ts.tv_sec += 2;
644	
645	    if (sem_timedwait(&s_stop_sem, &ts) != 0) {
646	        syslog(LOG_WARNING,
647	            "[%s] async stop timed out, forcing cleanup\n", TAG);
648	        /* Fallback: NULL out pointers without deleting (leak is
649	         * acceptable during shutdown to avoid crash). */
650	        s_state.screen = NULL;
651	        s_state.chat_list = NULL;
652	        s_state.ptt_btn = NULL;
653	        s_state.ptt_label = NULL;
654	        s_state.rec_indicator = NULL;
655	        s_state.close_btn = NULL;
656	    }
657	
658	    sem_destroy(&s_stop_sem);
659	
660	    /* Destroy the mutex */
661	    pthread_mutex_destroy(&s_state.lock);
662	
663	    s_state.initialized = false;
664	
665	    lvgl_ui_join_event_loop();
666	
667	    syslog(LOG_INFO, "[%s] stopped\n", TAG);
668	}
