707	void lvgl_ui_channel_show(void)
708	{
709	    if (!s_state.initialized || !s_state.running) {
710	        syslog(LOG_ERR, "[%s] show: channel not ready\n", TAG);
711	        return;
712	    }
713	
714	    if (s_state.screen_visible) {
715	        return;
716	    }
717	
718	    /* Ask rather than schedule: the event loop picks this up on its next
719	     * pass. See the note on the queue -- lv_async_call() from here is what
720	     * corrupted LVGL's list. */
721	    pthread_mutex_lock(&s_queue_mtx);
722	    s_show_requested = true;
723	    pthread_mutex_unlock(&s_queue_mtx);
