726	/* Common body for every way a line reaches the screen. 'speak' is separate
727	 * from 'is_user' because the two callers want different things: an Agent
728	 * reply is worth reading aloud, a mirrored or user line is not. */
729	static int ui_post(const char* text, bool is_user, bool speak)
730	{
731	    async_msg_t* payload;
732	    int slot;
733	
734	    if (!text || text[0] == '\0') {
735	        return -EINVAL;
736	    }
737	
738	    if (!s_state.initialized || !s_state.running) {
739	        return -EINVAL;
740	    }
741	
742	    payload = malloc(sizeof(async_msg_t));
743	    if (!payload) {
744	        syslog(LOG_ERR, "[%s] queue payload alloc failed\n", TAG);
745	        return -ENOMEM;
746	    }
747	
748	    strncpy(payload->text, text, LVGL_UI_MSG_MAX_LEN - 1);
749	    payload->text[LVGL_UI_MSG_MAX_LEN - 1] = '\0';
750	    payload->is_user = is_user;
751	
752	    pthread_mutex_lock(&s_queue_mtx);
753	
754	    if (s_queue_count == UI_QUEUE_MAX) {
755	        /* Full: drop the oldest so the line the user just caused still
756	         * gets through. Losing the tail of a burst is better than losing
757	         * the thing that prompted it. */
758	        free(s_queue[s_queue_head]);
759	        s_queue[s_queue_head] = NULL;
760	        s_queue_head = (s_queue_head + 1) % UI_QUEUE_MAX;
761	        s_queue_count--;
762	    }
763	
764	    slot = (s_queue_head + s_queue_count) % UI_QUEUE_MAX;
765	    s_queue[slot] = payload;
766	    s_queue_count++;
767	
768	    /* First line of any kind brings the chat screen up */
769	    s_show_requested = true;
770	
771	    pthread_mutex_unlock(&s_queue_mtx);
772	
773	    if (speak) {
774	        /* TTS is blocking — run after queueing the UI update */
775	        int ret = voice_channel_speak(text);
776	        if (ret != 0) {
777	            syslog(LOG_ERR, "[%s] voice_channel_speak failed (rc=%d)\n",
778	                TAG, ret);
779	        }
780	    }
781	
782	    return 0;
783	}
