785	/* Take everything queued and put it on screen. Runs on the LVGL thread only,
786	 * so it is the one place allowed to create or touch widgets. */
787	static void ui_drain(void)
788	{
789	    async_msg_t* batch[UI_QUEUE_MAX];
790	    bool show;
791	    bool stale = false;
792	    int n = 0;
793	    int i;
794	
795	    /* PTT latches "processing" until a line lands. If the host is gone or
796	     * the recogniser never answers, nothing lands and the button stays
797	     * dead forever. Re-enable it after a bounded wait. Runs on the LVGL
798	     * thread, so touching the indicator here is safe. */
799	    pthread_mutex_lock(&s_state.lock);
800	    if (s_state.is_processing && s_state.processing_started_ms != 0 &&
801	        (uint32_t)(lv_tick_get() - s_state.processing_started_ms) >=
802	            LVGL_UI_PROCESSING_TIMEOUT_MS) {
803	        s_state.is_processing = false;
804	        s_state.processing_started_ms = 0;
805	        stale = true;
806	    }
807	    pthread_mutex_unlock(&s_state.lock);
808	
809	    if (stale) {
810	        syslog(LOG_WARNING, "[%s] PTT processing timed out; button re-enabled\n",
811	               TAG);
812	        recording_indicator_stop();
813	    }
814	
815	    pthread_mutex_lock(&s_queue_mtx);
816	
817	    show = s_show_requested;
818	    s_show_requested = false;
819	
820	    while (s_queue_count > 0 && n < UI_QUEUE_MAX) {
821	        batch[n++] = s_queue[s_queue_head];
822	        s_queue[s_queue_head] = NULL;
823	        s_queue_head = (s_queue_head + 1) % UI_QUEUE_MAX;
824	        s_queue_count--;
825	    }
826	
827	    pthread_mutex_unlock(&s_queue_mtx);
828	
829	    if (show && !s_state.screen_visible) {
830	        show_screen_async_cb(NULL);
831	    }
832	
833	    for (i = 0; i < n; i++) {
834	        chat_view_add_message(batch[i]->text, batch[i]->is_user);
835	        free(batch[i]);
836	        batch[i] = NULL;
837	    }
838	
839	    /* A line landing means recognition finished -- either the recognised
840	     * command itself or the answer to it -- so the "识别中..." indicator has
841	     * done its job and goes back to idle. */
842	    if (n > 0 && s_state.is_processing) {
843	        s_state.is_processing = false;
844	        s_state.processing_started_ms = 0;
845	        recording_indicator_stop();
846	    }
847	}
