880	static void chat_view_add_message(const char* text, bool is_user)
881	{
882	    chat_history_t* h = &s_state.history;
883	    chat_msg_t* slot;
884	    lv_obj_t* bubble;
885	    lv_obj_t* lbl;
886	
887	    /* If history is already full, trim before overwriting */
888	    if (h->count == CHAT_HISTORY_MAX) {
889	        chat_view_trim_history();
890	    }
891	
892	    /* Store message in ring buffer (handles truncation + old bubble deletion) */
893	    slot = chat_history_add(h, text, is_user);
894	
895	    /* Create bubble container inside chat_list */
896	    bubble = lv_obj_create(s_state.chat_list);
897	    if (!bubble) {
898	        syslog(LOG_ERR, "[%s] bubble create failed\n", TAG);
899	        return;

900	    }
901	
902	    lv_obj_set_width(bubble, lv_pct(85));
903	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
904	    lv_obj_set_style_radius(bubble, LVGL_UI_BUBBLE_RADIUS, 0);
905	    lv_obj_set_style_pad_all(bubble, LVGL_UI_BUBBLE_PAD, 0);
906	    lv_obj_set_style_border_width(bubble, 0, 0);
907	
908	    if (is_user) {
909	        /* User bubble: right-aligned, blue background, white text */
910	        lv_obj_set_style_align(bubble, LV_ALIGN_RIGHT_MID, 0);
911	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x3a7bd5), 0);
912	        lv_obj_set_style_text_color(bubble, lv_color_white(), 0);
913	    } else {
914	        /* Agent bubble: left-aligned, semi-transparent dark bg */
915	        lv_obj_set_style_align(bubble, LV_ALIGN_LEFT_MID, 0);
916	        lv_obj_set_style_bg_color(bubble, lv_color_hex(0x2a2a40), 0);
917	        lv_obj_set_style_bg_opa(bubble, LV_OPA_90, 0);
918	        lv_obj_set_style_text_color(bubble, lv_color_hex(0xe8e8e8), 0);
919	    }
920	
921	    /* Create label inside bubble */
922	    lbl = lv_label_create(bubble);
923	    if (!lbl) {
924	        syslog(LOG_ERR, "[%s] bubble label create failed\n", TAG);
925	        lv_obj_del(bubble);
926	        slot->bubble = NULL;
927	        return;
928	    }
929	
930	    lv_label_set_text(lbl, slot->text);
931	    lv_label_set_long_mode(lbl, LV_LABEL_LONG_WRAP);
932	    lv_obj_set_width(lbl, lv_pct(100));
933	
934	    slot->bubble = bubble;
935	
936	    chat_view_scroll_to_bottom();
937	}
