951	static void ptt_btn_event_cb(lv_event_t* e)
952	{
953	    lv_event_code_t code = lv_event_get_code(e);
954	
955	    /* Single-click toggle: first click starts recording, second stops.
956	     *
957	     * Note what this means for the operator: the recording runs *between*
958	     * the two clicks. Click, speak, click again -- a quick double-click
959	     * captures the silence in between and nothing else, which is what the
960	     * other end reports as "too short" or "nothing recognised". */
961	    if (code != LV_EVENT_CLICKED) {
962	        return;
963	    }
964	
965	    pthread_mutex_lock(&s_state.lock);
966	
967	    if (s_state.is_processing) {
968	        pthread_mutex_unlock(&s_state.lock);
969	        return;
970	    }
971	
972	    if (!s_state.is_recording) {
973	        s_state.is_recording = true;
974	        pthread_mutex_unlock(&s_state.lock);
975	
976	        /* The microphone already streams to the host continuously; this
977	         * frame only says that whatever arrives from now on was meant as a
978	         * command. Recognition stays on the host because that is the only
979	         * place with a recogniser: this board's own voice channel wants
980	         * /dev/audio/pcm0c, and there is no NuttX audio driver under it, so
981	         * the button used to answer every press with "录音启动失败".
982	         * The other end is voice_bridge.py (see its "ptt" handler). */
983	        ws_server_broadcast_json("{\"type\":\"ptt\",\"state\":\"start\"}");
984	        recording_indicator_start();
985	    } else {
986	        s_state.is_recording = false;
987	        s_state.is_processing = true;
988	        s_state.processing_started_ms = lv_tick_get();
989	        pthread_mutex_unlock(&s_state.lock);
990	
991	        ws_server_broadcast_json("{\"type\":\"ptt\",\"state\":\"stop\"}");
992	        recording_indicator_show_processing();
993	    }
994	}
