static void dock_btn_cb(lv_event_t* e)
{
    int idx = (int)(intptr_t)lv_event_get_user_data(e);

    ui_show_page(idx);
}

static void tileview_event_cb(lv_event_t* e)
{
    lv_obj_t* active;

    if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED) {
        return;
    }

    active = lv_tileview_get_tile_active(s_state.tileview);
    if (active == s_state.chat_page) {
        ui_update_dock(1);
    } else if (active == s_state.status_page) {
        ui_update_dock(2);
    } else {
        ui_update_dock(0);
    }
}

static void ui_update_dock(int idx)
{
    int i;

    for (i = 0; i < 3; i++) {
        if (!s_state.dock_btn[i]) {
            continue;
        }
        lv_obj_set_style_bg_color(s_state.dock_btn[i],
            i == idx ? lv_color_hex(0x4a90d9) : lv_color_hex(0x2a2a40), 0);
    }
}

static void ui_show_page(int idx)
{
    if (!s_state.tileview) {
        return;
    }
    if (idx < 0 || idx > 2) {
        idx = 0;
    }
    lv_tileview_set_tile_by_index(s_state.tileview, (uint32_t)idx, 0,
                                  LV_ANIM_ON);
    ui_update_dock(idx);
}

static void create_dock(lv_obj_t* parent)
{
    static const char* labels[] = {"主页", "对话", "状态"};
