    s_state.dock_w = s_state.safe_w < 200 ? s_state.safe_w : 200;
    lv_obj_set_size(dock, s_state.dock_w, UI_DOCK_H);
    lv_obj_align(dock, LV_ALIGN_BOTTOM_MID, 0, UI_DOCK_Y);
    lv_obj_set_style_bg_opa(dock, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(dock, 0, 0);
