/* The board's LCD is brought up by an asynchronous init thread in
 * sifli_ap.c; on a cold boot /dev/lcd0 can appear several seconds after
 * NSH.  The agent used to start first and LVGL then failed with
 * "cannot open lcd device: Error 2", leaving a headless CLI.  Wait for
 * the device node (yielding to the higher-priority init thread) before
 * asking LVGL to open it. */
static bool ui_wait_for_device(const char* path, int timeout_ms)
{
    int waited = 0;

    while (waited < timeout_ms) {
        if (access(path, F_OK) == 0) {
            return true;
        }
        usleep(100000);
        waited += 100;
    }
    return access(path, F_OK) == 0;
}

