static void status_timer_cb(lv_timer_t* t)
{
    ui_status_snapshot_t snap;
    static uint32_t last_seq;
    int ram_pct;

    (void)t;
    pthread_mutex_lock(&s_state.status_lock);
    snap = s_state.status_snap;
    pthread_mutex_unlock(&s_state.status_lock);
    if (!snap.valid || snap.seq == last_seq) return;
    last_seq = snap.seq;
    ram_pct = snap.ram_total ? (int)((snap.ram_used*100U)/snap.ram_total) : 0;

    if (s_state.home_ram) {
        if (snap.ram_total) lv_label_set_text_fmt(s_state.home_ram, "%d%%", ram_pct);
        else lv_label_set_text(s_state.home_ram, "--");
    }
    if (s_state.home_task) lv_label_set_text_fmt(s_state.home_task, "%d", snap.task_count);
    if (s_state.home_net) {
        lv_label_set_text(s_state.home_net, snap.net_up ? "在线" : "离线");
        lv_obj_set_style_text_color(s_state.home_net,
            lv_color_hex(snap.net_up ? UI_C_TEAL : UI_C_DIM), 0);
    }
    if (s_state.home_cron) lv_label_set_text_fmt(s_state.home_cron, "%d", snap.cron_count);

    if (s_state.status_net) {
        lv_label_set_text(s_state.status_net, snap.net_up ? "在线" : "离线");
        lv_obj_set_style_text_color(s_state.status_net,
            lv_color_hex(snap.net_up ? UI_C_TEAL : UI_C_DIM), 0);
    }
    if (s_state.status_ram_label) {
        if (snap.ram_total) {
            lv_label_set_text_fmt(s_state.status_ram_label, "%d%%  %lu/%lu MB",
                ram_pct, (unsigned long)(snap.ram_used/1024U),
                (unsigned long)(snap.ram_total/1024U));
        } else {
            lv_label_set_text(s_state.status_ram_label, "--");
        }
    }
    if (s_state.status_ram_bar) lv_bar_set_value(s_state.status_ram_bar, ram_pct, LV_ANIM_OFF);
    if (s_state.status_task_label) {
        if (snap.min_prio < 255) {
            lv_label_set_text_fmt(s_state.status_task_label, "%d 个 / 最高 %d",
                                  snap.task_count, snap.min_prio);
        } else {
            lv_label_set_text_fmt(s_state.status_task_label, "%d 个", snap.task_count);
        }
    }
    if (s_state.status_net_label) {
        if (snap.net_up && snap.ip[0]) lv_label_set_text_fmt(s_state.status_net_label, "%s", snap.ip);
        else lv_label_set_text(s_state.status_net_label, snap.net_up ? "在线" : "离线");
        lv_obj_set_style_text_color(s_state.status_net_label,
