    if (s_state.status_cron_label) lv_label_set_text_fmt(s_state.status_cron_label, "%d", snap.cron_count);
    if (s_state.status_uptime_label) lv_label_set_text_fmt(s_state.status_uptime_label,
        "%luh %lum", (unsigned long)(snap.uptime_s/3600U), (unsigned long)((snap.uptime_s/60U)%60U));
}
